<template>
  <div class="berry-backdrop" @keydown.stop="keys" @keyup.stop>
    <section ref="dialog" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="berry-title" class="berry-panel" :class="{mutator}">
      <header><housing-item-icon :item-key="mutator?'berry_mutator':payload.slots===3?'berry_planter':'berry_pot'"/><div><small>CHEZ TOI · ATELIER DES BAIES</small><h2 id="berry-title">{{mutator?'Mutateur de baies':'Tes cultures'}}</h2></div><button aria-label="Fermer" :disabled="busy" @click="close">×</button></header>
      <nav v-if="mutator" aria-label="Atelier"><button :aria-pressed="tab==='mix'" @click="tab='mix'">Mutation</button><button :aria-pressed="tab==='recipes'" @click="tab='recipes'">Carnet · {{payload.recipes.length}}</button></nav>
      <div class="berry-body">
        <template v-if="!mutator">
          <p class="berry-intro">Une baie, {{crystalCost}} Éclats fissurés et vingt minutes. Chaque plant pousse à son rythme, même en ton absence.</p>
          <div class="berry-crops">
            <button v-for="(crop,index) in crops" :key="index" :aria-pressed="slot===index" class="berry-crop" :class="crop.stage" @click="slot=index">
              <span class="crop-number">{{index+1}}</span><span class="crop-sprite" :style="growthStyle(crop)"/><b>{{crop.stage==='empty'?'Terre libre':label(crop.berryKey)}}</b><small>{{crop.stage==='mature'?'Prête à récolter':crop.stage==='empty'?'Une nouvelle plantation ?':remaining(crop.remainingMs)}}</small><progress v-if="crop.stage!=='empty'" :value="1200000-crop.remainingMs" max="1200000"/>
            </button>
          </div>
          <section v-if="plantFavorites.length" class="plant-favorites" aria-label="Plantations favorites">
            <div class="plant-favorites-heading"><h3>Plantations favorites</h3><small>Le coût habituel, sans refaire les dépôts.</small></div>
            <div class="plant-favorite-list">
              <article v-for="preset in plantFavorites" :key="preset.key" class="plant-favorite-card" :data-plant-preset="preset.key">
                <button class="plant-favorite-remove" :disabled="busy||!!pending" aria-label="Retirer cette plantation des favoris" @click="togglePlantFavorite(preset.berries)">★</button>
                <div class="plant-favorite-icons"><span v-for="(key,index) in preset.berries" :key="index"><berry-icon v-if="key" :item-key="key"/><span v-else class="empty-plant-icon">·</span><small v-if="preset.berries.length>1">{{index+1}}</small></span></div>
                <b>{{preset.berries.length===1?label(preset.berries[0]):'Ta composition'}}</b>
                <small class="plant-favorite-cost">{{presetCost(preset.berries)}}</small>
                <div class="plant-favorite-actions"><button data-plant-preset-use :disabled="busy||!!pending||!canPlant(presetPlans(preset.berries))" @click="replant(preset.berries)">{{preset.berries.length===1?'Planter':'Replanter les trous libres'}}</button><button v-if="preset.berries.length===1&&payload.slots===3&&emptySlots.length>1" data-plant-preset-fill :disabled="busy||!!pending||!canPlant(presetPlans(preset.berries,true))" @click="replant(preset.berries,true)">Remplir les {{emptySlots.length}} trous</button></div>
              </article>
            </div>
          </section>
          <div class="harvest-all"><span>{{matureCount ? matureCount+' récolte'+(matureCount>1?'s':'')+' prête'+(matureCount>1?'s':'') : 'Les plants poussent chacun à leur rythme.'}}</span><button :disabled="busy||!!pending||!matureCount" @click="act('harvestAll',{})">Tout récolter<span v-if="matureCount"> · {{matureCount}}</span></button></div>
          <p v-if="harvestNotice" class="harvest-notice" role="status">{{harvestNotice}}</p>
          <div v-if="copyBerry" class="plant-shortcuts">
            <button v-if="showCopy" class="plant-copy" data-plant-copy :disabled="busy||!!pending||!canPlant(copyPlantings)" @click="act('plantMany',{plantings:copyPlantings})"><b>{{active.stage==='empty'?'Planter les '+copyPlantings.length+' trous libres':'Copier dans '+copyPlantings.length+' autre'+(copyPlantings.length>1?'s':'')+' trou'+(copyPlantings.length>1?'s':'')}}</b><small>{{copyPlantings.length}} baie{{copyPlantings.length>1?'s':''}} · {{copyPlantings.length*crystalCost}} Éclats fissurés</small></button>
            <button class="plant-save" data-plant-favorite-berry :aria-pressed="isPlantFavorite([copyBerry])" :disabled="busy||!!pending" @click="togglePlantFavorite([copyBerry])">{{isPlantFavorite([copyBerry])?'★':'☆'}} Cette baie</button>
            <button v-if="currentPlantation.filter(Boolean).length>1" class="plant-save" data-plant-favorite-layout :aria-pressed="isPlantFavorite(currentPlantation)" :disabled="busy||!!pending" @click="togglePlantFavorite(currentPlantation)">{{isPlantFavorite(currentPlantation)?'★':'☆'}} Cette plantation</button>
          </div>
          <div v-if="active.stage==='empty'" class="berry-planting">
            <div class="ingredient-socket" data-berry-drop="0" :class="{filled:chosen[0]}" @dragover.prevent @drop.prevent="drop($event,0)" @click="focusIngredient=0"><berry-icon v-if="chosen[0]" :item-key="chosen[0]"/><span>{{chosen[0]?label(chosen[0]):'Dépose une baie classique'}}</span></div>
            <span class="plus">+</span><button class="crystal-deposit" :aria-pressed="crystals" :disabled="shards<crystalCost" @click="!pending&&(crystals=!crystals)"><span aria-hidden="true">◈</span><b>{{crystalCost}} Éclats fissurés</b><small>{{crystals?'Cristaux déposés':crystalCost>shards?'Stock insuffisant':'Déposer les cristaux'}}</small></button>
          </div>
          <div v-else class="plant-detail"><b>{{active.stage==='mature'?'Ta baie a mûri.':'La corruption prend racine.'}}</b><p>{{active.stage==='mature'?'La récolte libère cet emplacement.':'Tu peux partir : la croissance continuera sans toi.'}}</p><button v-if="active.stage==='mature'" class="berry-primary" :disabled="busy||pending" @click="act('harvest',{slot})">Récolter {{label(active.berryKey)}} (Corrompue)</button></div>
        </template>
        <template v-else-if="tab==='mix'">
          <p class="berry-intro">Trois baies corrompues, une nouvelle mutation. Un mélange garde ses résultats possibles ; la rareté reste une surprise à chaque tentative.</p>
          <label class="batch-quantity">Quantité <input v-model.number="quantity" type="number" min="1" :max="maxBatch||1" :disabled="busy||!!pending"/><button :disabled="busy||!!pending||!maxBatch" @click="quantity=maxBatch">Max · {{maxBatch}}</button><small>Trois ingrédients par baie · {{Number(quantity)*3||0}} consommés au total</small></label><div v-if="batchResults.reduce((n,r)=>n+r.quantity,0)>1" class="batch-results" role="status"><span v-for="r in batchResults" :key="r.itemKey"><berry-icon :item-key="r.itemKey"/>{{label(r.itemKey)}} × {{r.quantity}}</span></div><div class="mutator-tray" :class="{working:busy}"><div v-for="(_,index) in chosen" :key="index" class="ingredient-socket" :class="{filled:chosen[index],focused:focusIngredient===index}" :data-berry-drop="index" @dragover.prevent @drop.prevent="drop($event,index)" @click="focusIngredient=index"><button v-if="chosen[index]" aria-label="Retirer cette baie" class="remove" :disabled="busy" @click.stop="!pending&&$set(chosen,index,null)">×</button><berry-icon v-if="chosen[index]" :item-key="chosen[index]"/><span>{{chosen[index]?label(chosen[index]):'Baie '+(index+1)}}</span></div></div>
          <div class="mutation-odds"><span class="failed">20 % ratée</span><span class="common">50 % commune</span><span class="rare">25 % rare</span><span class="legendary">5 % légendaire</span></div>
          <p class="berry-permanent">Une baie mutée peut être tenue par tout Pokémon. Elle est consommée définitivement à son entrée en combat, dans tous les modes ; ses effets cessent au retrait.</p>
          <div v-if="result" :key="result.key+'-'+resultCount" class="mutation-result" :class="result.rarity" role="status"><berry-icon :item-key="result.itemKey"/><div><small>{{rarities[result.rarity]}}</small><h3>{{label(result.itemKey)}}</h3><p>{{definition(result.itemKey).description}}</p></div></div>
        </template>
        <div v-else class="recipe-register">
          <label class="recipe-search"><span>Rechercher dans ton carnet</span><input v-model="recipeQuery" type="search" placeholder="Défense, Fée, nom d’une baie…" aria-label="Rechercher une recette"/></label>
          <p v-if="!payload.recipes.length" class="berry-empty">Ton carnet est encore vierge. Essaie un premier mélange pour y noter ses résultats possibles.</p>
          <p v-else-if="!filteredRecipes.length" class="berry-empty">Aucune recette ne correspond à ta recherche.</p>
          <article v-for="r in filteredRecipes" :key="r.key" :class="{'is-favorite':r.favorite}">
            <div class="recipe-heading">
              <button class="recipe-favorite" :class="{selected:r.favorite}" :aria-label="(r.favorite?'Retirer des favoris : ':'Ajouter aux favoris : ')+r.name" :aria-pressed="!!r.favorite" :disabled="busy||!!pending" @click="act('favorite',{recipeKey:r.key,favorite:!r.favorite})">{{r.favorite?'★':'☆'}}</button>
              <button class="recipe-toggle" :aria-expanded="expandedRecipes.includes(r.key)" :aria-controls="'recipe-'+r.key" @click="toggleRecipe(r.key)">
                <span><b>{{r.name}}</b><small>{{r.attempts}} essai{{r.attempts>1?'s':''}} · 3 résultats possibles</small><span class="recipe-rarities"><span class="common">Commune</span><span class="rare">Rare</span><span class="legendary">Légendaire</span></span></span>
                <span class="recipe-chevron" aria-hidden="true">{{expandedRecipes.includes(r.key)?'⌃':'⌄'}}</span>
              </button>
            </div>
            <div v-if="expandedRecipes.includes(r.key)" :id="'recipe-'+r.key" class="recipe-details">
              <div class="recipe-ingredients"><span v-for="(key,i) in r.ingredients" :key="i"><berry-icon :item-key="key"/><small>{{label(key)}}</small></span><button :disabled="busy||!!pending" @click="reuse(r)">Refaire →</button></div>
              <div class="recipe-outcomes"><div v-for="rarity in ['common','rare','legendary']" :key="rarity" :class="rarity"><berry-icon :item-key="r.results[rarity]"/><b>{{label(r.results[rarity])}}</b><small>{{definition(r.results[rarity]).description}}</small></div></div>
            </div>
          </article>
        </div>
        <section v-if="(!mutator&&active.stage==='empty')||(mutator&&tab==='mix')" class="berry-stock"><div class="stock-heading"><h3>{{mutator?'Baies corrompues':'Tes baies classiques'}}</h3><span>{{mutator?'Choisis un emplacement, puis une baie':'Glisse une baie ou touche son nom'}}</span></div><input v-model="query" type="search" placeholder="Rechercher une baie…" aria-label="Rechercher une baie"/><p v-if="!stock.length" class="berry-empty">{{mutator?'Récolte des baies corrompues dans tes pots pour commencer.':'Il te faut une baie classique pour planter.'}}</p><div class="berry-stock-list"><button v-for="i in stock" :key="i.key" :disabled="busy||available(i.key)<1" :title="i.description" @click="choose(i.key)"><span class="berry-drag" draggable="true" @dragstart="drag($event,i.key)" @pointerdown="pointerStart($event,i.key)"><berry-icon :item-key="i.key"/></span><span><b>{{i.name}}</b><small>× {{available(i.key)}}</small></span></button></div></section>
      </div>
      <p v-if="error" class="berry-error" role="alert">{{error}}</p><p v-if="localError" class="berry-error" role="alert">{{localError}}</p>
      <footer><span>{{mutator?'Trois ingrédients consommés par tentative.':shards.toLocaleString('fr-FR')+' Éclats fissurés en réserve'}}</span><button v-if="pending" :disabled="busy" @click="retry">Vérifier l’enregistrement</button><button v-else-if="mutator&&tab==='mix'" class="berry-primary" :disabled="busy||!canMutate||quantity<1||quantity>maxBatch" @click="act('mutate',{ingredients:[...chosen],quantity:Number(quantity)})">{{busy?'Mutation en cours…':'Fabriquer × '+quantity}}</button><button v-else-if="!mutator&&active.stage==='empty'" class="berry-primary" :disabled="busy||!chosen[0]||!crystals" @click="act('plant',{slot,berryKey:chosen[0]})">Planter · 20 min</button><button v-else @click="close">Fermer</button></footer>
    </section>
  </div>
</template>
<script>
import BerryIcon from '../menu/BerryIcon.vue';
import HousingItemIcon from './HousingItemIcon.vue';
import definitions from '@/data/berryItems.json';
import berryRules from '@/data/berryMutation.json';
import {indexRecipes,findRecipes} from '@/services/berryRecipes';
import {normalizedPlanting,samePlanting,favoritePlantings,canAffordPlanting} from '@/services/berryPlantings';
const catalog=new Map(definitions.map(i=>[i.key,i]));
export default{
 components:{BerryIcon,HousingItemIcon},props:{payload:Object,busy:Boolean,error:String,command:Function},
 data:()=>({slot:0,chosen:[null,null,null],crystals:false,tab:'mix',query:'',recipeQuery:'',expandedRecipes:[],harvestNotice:'',focusIngredient:0,clock:Date.now(),pending:null,result:null,resultCount:0,batchResults:[],quantity:1,localError:'',rarities:{failed:'Mutation ratée',common:'Mutation commune',rare:'Mutation rare',legendary:'Mutation légendaire'}}),
 computed:{
 plantFavorites(){return (this.payload.plantFavorites||[]).filter(p=>p.berries.length<=this.payload.slots);},
 emptySlots(){return this.crops.flatMap((crop,slot)=>crop.stage==='empty'?[slot]:[]);},
 copyBerry(){return this.active.berryKey||this.chosen[0];},
 copyPlantings(){return this.copyBerry?this.emptySlots.map(slot=>({slot,berryKey:this.copyBerry})):[];},
 showCopy(){return this.payload.slots===3&&this.copyPlantings.length>(this.active.stage==='empty'?1:0);},
 currentPlantation(){return normalizedPlanting(this.crops.map((crop,index)=>crop.berryKey||(index===this.slot?this.chosen[0]:null)));},
 maxBatch(){const counts=new Map();for(const key of this.chosen){if(!key)return 0;counts.set(key,(counts.get(key)||0)+1);}return Math.min(50,...[...counts].map(([key,n])=>Math.floor((this.payload.items.find(i=>i.key===key)?.quantity||0)/n)));},crystalCost(){return berryRules.crystalCost;},recipeIndex(){return indexRecipes(this.payload.recipes,catalog);},filteredRecipes(){return findRecipes(this.recipeIndex,this.recipeQuery);},matureCount(){return this.crops.filter(c=>c.stage==='mature').length;},canMutate(){const counts=new Map();for(const k of this.chosen){if(!k)return false;counts.set(k,(counts.get(k)||0)+1);}return [...counts].every(([k,n])=>(this.payload.items.find(i=>i.key===k)?.quantity||0)>=n);},mutator(){return this.payload.kind==='mutator';},now(){return this.clock+(this.payload.serverNow-this._receivedAt||0);},crops(){return Array.from({length:this.payload.slots||1},(_,slot)=>{const c=this.payload.home.crops?.find(x=>x.furnitureId===this.payload.furnitureId&&x.slot===slot);if(!c)return{stage:'empty'};const elapsed=Math.max(0,this.now-c.plantedAt);return{...c,stage:elapsed>=1200000?'mature':elapsed>=300000?'sprout':'seed',remainingMs:Math.max(0,1200000-elapsed)};});},active(){return this.crops[this.slot]||{stage:'empty'};},shards(){return this.payload.items.find(i=>i.key==='crystal_shard')?.quantity||0;},stock(){return this.payload.items.filter(i=>(this.mutator?i.berryKind==='ingredient':catalog.get(i.key)?.classic)&&i.name.toLocaleLowerCase().includes(this.query.toLocaleLowerCase()));}},
 watch:{'payload.serverNow'(){this._receivedAt=Date.now();}},
 mounted(){this._receivedAt=Date.now();this._timer=setInterval(()=>this.clock=Date.now(),1000);this.$refs.dialog.focus({preventScroll:true});},beforeDestroy(){clearInterval(this._timer);this.clearPointer?.();},
 methods:{
 isPlantFavorite(berries){return this.plantFavorites.some(p=>samePlanting(p.berries,berries));},
 canPlant(plantings){return canAffordPlanting(plantings,this.payload.items,this.crystalCost);},
 presetPlans(berries,fill=false){return favoritePlantings(berries,this.crops,this.slot,fill);},
 presetCost(berries){const plans=this.presetPlans(berries);return !plans.length?'Tous les emplacements concernés sont occupés.':plans.length+' baie'+(plans.length>1?'s':'')+' · '+plans.length*this.crystalCost+' Éclats fissurés';},
 replant(berries,fill=false){const plantings=this.presetPlans(berries,fill);if(this.canPlant(plantings))this.act('plantMany',{plantings});},
 togglePlantFavorite(berries){this.act('plantFavorite',{berries:normalizedPlanting(berries),favorite:!this.isPlantFavorite(berries)});},
 toggleRecipe(key){const n=this.expandedRecipes.indexOf(key);if(n<0)this.expandedRecipes.push(key);else this.expandedRecipes.splice(n,1);},definition:k=>catalog.get(k)||{},label:k=>catalog.get(k)?.name||k,remaining(ms){const n=Math.ceil(ms/1000);return Math.floor(n/60)+' min '+String(n%60).padStart(2,'0')+' s';},growthStyle(c){const index={seed:0,sprout:1,mature:2}[c.stage];return index===undefined?{}:{backgroundImage:'url('+require('@/assets/berries/growth-v1.png')+')',backgroundPosition:(-index*64)+'px 0'};},available(k){return Math.max(0,(this.payload.items.find(x=>x.key===k)?.quantity||0)-this.chosen.filter(x=>x===k).length);},choose(k,index=this.mutator?this.focusIngredient:0){if(this.pending)return;if(this.available(k)<1&&this.chosen[index]!==k)return;this.$set(this.chosen,index,k);if(this.mutator)this.focusIngredient=this.chosen.findIndex(x=>!x);if(this.focusIngredient<0)this.focusIngredient=0;},drag(e,k){e.dataTransfer.setData('text/plain',k);},drop(e,index){const key=e.dataTransfer.getData('text/plain');if(this.stock.some(i=>i.key===key))this.choose(key,index);},pointerStart(e,key){if(e.button!==0&&e.pointerType==='mouse')return;const start={x:e.clientX,y:e.clientY},move=ev=>{if(Math.hypot(ev.clientX-start.x,ev.clientY-start.y)>8)ev.preventDefault();},up=ev=>{const node=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-berry-drop]');if(node)this.choose(key,Number(node.dataset.berryDrop));this.clearPointer();};this.clearPointer?.();this.clearPointer=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);};window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',up);window.addEventListener('pointercancel',up);},async act(name,data){this.localError='';if(!this.pending)this.pending={name,data:{...data,floor:this.payload.floor,furnitureId:this.payload.furnitureId,revision:this.payload.home.revision,requestId:crypto.randomUUID()}};await this.retry();},async retry(){const request=this.pending;if(!request)return;const r=await this.command(request.name,request.data);if(!r)return;if(r.success===false){if(!r.retryable)this.pending=null;return;}this.pending=null;if(!['favorite','plantFavorite'].includes(request.name)){this.chosen=[null,null,null];this.crystals=false;}if(r.receipt?.planted)this.harvestNotice=r.receipt.planted.length+' plant'+(r.receipt.planted.length>1?'s':'')+' mis en terre. Chaque plant a consommé une baie et '+this.crystalCost+' Éclats fissurés.';if(r.receipt?.harvested)this.harvestNotice=r.receipt.harvested.length+' baie'+(r.receipt.harvested.length>1?'s récoltées.':' récoltée.');if(r.receipt?.mutation){this.result=r.receipt.mutation;this.batchResults=r.receipt.mutations||[];this.resultCount++;}},reuse(r){if(this.pending)return;this.chosen=[...r.ingredients];this.tab='mix';this.query='';},keys(e){if(e.key==='Escape')this.close();},close(){if(!this.busy)this.$emit('close');}}
};
</script>
<style scoped>
